import{_ as a,o,c as t,a7 as r}from"./chunks/framework.BTQh61J2.js";const u=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1791538191000}'),d={name:"guide/faq.md"};function l(i,e,c,s,n,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="点击后没有进入原生全屏" tabindex="-1">点击后没有进入原生全屏？ <a class="header-anchor" href="#点击后没有进入原生全屏" aria-label="Permalink to &quot;点击后没有进入原生全屏？&quot;">​</a></h2><p>先检查错误事件或 Promise 拒绝。浏览器需要直接的用户手势；在网络请求、计时器或自动挂载之后请求，可能被拒绝。嵌入 iframe 时还需要宿主允许 fullscreen 权限。</p><p><code>isEnabled</code> 只表示 API 可用，不保证每次请求都被批准。可先启用 <code>pageOnly</code>，排除原生权限问题。</p><h2 id="手机上的表现为什么不同" tabindex="-1">手机上的表现为什么不同？ <a class="header-anchor" href="#手机上的表现为什么不同" aria-label="Permalink to &quot;手机上的表现为什么不同？&quot;">​</a></h2><p>不同浏览器、设备及嵌入方式的原生全屏支持不同。不支持时库会降级到网页全屏；网页全屏仍保留浏览器工具栏。请在目标设备上验证，而不是根据桌面浏览器推断。</p><h2 id="弹窗或下拉菜单看不到" tabindex="-1">弹窗或下拉菜单看不到？ <a class="header-anchor" href="#弹窗或下拉菜单看不到" aria-label="Permalink to &quot;弹窗或下拉菜单看不到？&quot;">​</a></h2><p>尝试开启 <code>teleport</code>，让原生全屏的目标变成 body。弹窗本身的挂载位置和层级仍由 UI 库决定。网页全屏时可为 <code>fullscreenClass</code> 指定合适的背景、<code>z-index</code> 和滚动样式。</p><h2 id="teleport-后样式变了" tabindex="-1">teleport 后样式变了？ <a class="header-anchor" href="#teleport-后样式变了" aria-label="Permalink to &quot;teleport 后样式变了？&quot;">​</a></h2><p>元素从原父节点移动到了 body。依赖祖先的 CSS 选择器和继承值可能失效；把关键样式放到目标自身的 class 上。退出时会恢复原 DOM 位置和被库修改的行内布局样式。</p><h2 id="ssr-或-nuxt-可以用吗" tabindex="-1">SSR 或 Nuxt 可以用吗？ <a class="header-anchor" href="#ssr-或-nuxt-可以用吗" aria-label="Permalink to &quot;SSR 或 Nuxt 可以用吗？&quot;">​</a></h2><p>可以在服务端导入包。只在浏览器挂载后读取 DOM，并在用户操作中请求原生全屏。不要在服务端调用 <code>api.request()</code>。VitePress 文档里的交互示例通过 <code>ClientOnly</code> 渲染。</p><h2 id="api-状态为什么没有更新页面" tabindex="-1">API 状态为什么没有更新页面？ <a class="header-anchor" href="#api-状态为什么没有更新页面" aria-label="Permalink to &quot;API 状态为什么没有更新页面？&quot;">​</a></h2><p><code>api.isFullscreen</code> 不是响应式引用。使用 <code>callback</code> 写入 Vue 状态，或改用组件的 <code>v-model</code>。</p><h2 id="切换路由后如何清理" tabindex="-1">切换路由后如何清理？ <a class="header-anchor" href="#切换路由后如何清理" aria-label="Permalink to &quot;切换路由后如何清理？&quot;">​</a></h2><p>组件会在卸载时清理。直接使用 API 或指令时，在路由移除全屏目标之前等待 <code>api.exit()</code>。指令卸载只负责移除点击处理器，不代表它拥有整个共享 API 会话。</p>',16)])])}const f=a(d,[["render",l]]);export{u as __pageData,f as default};
